<script lang="ts">
 import {onMount} from 'svelte';
 let ready=$state(false);
 onMount(()=>{ready=true;if(new URL(window.location.href).searchParams.has('command'))commandInput?.focus();});
 import {sourceHref,severityLabels,autonomyLabels,riskLabels,type Briefing,type BobActivity,type AutomationCenter,type BobCommand,type Workflow} from '$lib/bob-intelligence';
 let {data,form}:{data:{briefing:Briefing|null;activity:BobActivity|null;automation:AutomationCenter|null;tab:string;basePath:string;unavailable:string|null;canAct:boolean;planKey:string};form?:{message?:string;failed?:boolean;command?:BobCommand;proposedWorkflow?:Workflow}|null}=$props();
 let commandInput = $state<HTMLInputElement>();
 const conditions=['follow-up-overdue','missing-qualification','proposal-no-response','pricing-blocked','readiness-blocked','material-shortage','po-overdue','overdue-open-item','close-blocked','time-exception'];
 const approvalFields=['subject','body','text','startUtc','endUtc','state','action','id','targetId'];
 const date=(s:string)=>new Date(s).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
 function shortcut(e:KeyboardEvent){if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();commandInput?.focus();}}
</script>
<svelte:window onkeydown={shortcut}/>
<svelte:head><title>Bob · Daily intelligence</title></svelte:head>
<div class="intelligence" data-ready={ready}>
 <header><div><p class="eyebrow">Bob</p><h1>{data.tab==='activity'?'Bob Activity':data.tab==='automation'?'Automation Center':'What matters today'}</h1></div>
 <nav aria-label="Bob intelligence"><a href="?view=today" aria-current={data.tab==='today'?'page':undefined}>Today</a><a href="?view=activity" aria-current={data.tab==='activity'?'page':undefined}>Activity</a><a href="?view=automation" aria-current={data.tab==='automation'?'page':undefined}>Automation</a></nav></header>
 {#if data.unavailable}<div role="alert" class="notice"><p>{data.unavailable}</p><a href="?view=today">Retry briefing</a></div>{/if}
 {#if form?.message}<p class="notice" role={form.failed?'alert':'status'}>{form.message}</p>{/if}
 {#if form?.proposedWorkflow}<section aria-label="Proposed workflow"><h2>{form.proposedWorkflow.goal}</h2><ol>{#each form.proposedWorkflow.steps as step}<li>{step.rationale}</li>{/each}</ol><form method="POST" action="?/workflow"><input type="hidden" name="id" value={form.proposedWorkflow.id}/><input type="hidden" name="operation" value="advance"/><button>Continue with these steps</button></form><p class="muted">Any required human approval stops the workflow before that action.</p></section>{/if}
 {#if data.tab==='today'}
 <form method="POST" action="?/command" class="command"><label for="bob-command">Ask Bob <span class="muted">⌘ / Ctrl K</span></label><div><input bind:this={commandInput} id="bob-command" name="text" required maxlength="2000" placeholder="What needs my attention?"/><button>Review</button></div></form>
 {#if form?.command}<section aria-label="Command result"><h2>{form.command.status==='clarification_required'?'Choose a record':'Bob found'}</h2>{#each form.command.matches as fact}<article><h3>{fact.title}</h3><p>{fact.explanation}</p><a href={sourceHref(data.basePath,fact.source)}>Review {fact.source.module}</a><form method="POST" action="?/command"><input type="hidden" name="text" value="What is next for this record?"/><input type="hidden" name="module" value={fact.source.module}/><input type="hidden" name="entityId" value={fact.source.entityId}/><button class="quiet">Focus this record</button></form></article>{/each}</section>{/if}
 {#if data.briefing}
 {#if data.briefing.context.incompleteModules?.length}<p class="notice" role="status">Showing a bounded source window for {data.briefing.context.incompleteModules.join(', ')}. Existing attention remains open until a complete check.</p>{/if}
 <p class="muted">{data.briefing.context.role} · Checked {date(data.briefing.context.asOfUtc)}</p>
 {#if data.briefing.context.unavailableModules.length}<p class="notice" role="status">Some source checks are unavailable: {data.briefing.context.unavailableModules.join(', ')}. This briefing is incomplete.</p>{/if}
 <section aria-labelledby="priorities"><h2 id="priorities">Today's priorities</h2>
 {#each data.briefing.priorities as item}<article><div class="row"><span class="severity">{severityLabels[item.severity]} · {item.source.module}</span>{#if item.escalatedTo}<span class="muted">Escalated to {item.escalatedTo}</span>{/if}</div><h3>{item.title}</h3><p>{item.explanation}</p><p>{item.recommendedAction}</p><div class="actions"><a href={sourceHref(data.basePath,item.source)}>Review source</a>{#if data.canAct}<form method="POST" action="?/plan"><input type="hidden" name="id" value={item.id}/><input type="hidden" name="key" value={data.planKey+':'+item.id}/><label class="sr-only" for={'plan-'+item.id}>Next step for {item.title}</label><select id={'plan-'+item.id} name="goal"><option value="review">Review with Bob</option>{#if item.source.module==='leads'}<option value="assign-follow-up">Assign and prepare follow-up</option>{/if}{#if item.source.module==='jobs'}<option value="create-task">Create readiness task</option><option value="coordinate-readiness">Coordinate job and materials</option>{/if}</select><button>Prepare steps</button></form>{/if}<form method="POST" action="?/dismiss"><input type="hidden" name="id" value={item.id}/><button class="quiet">Dismiss</button></form>{#if data.canAct}<form method="POST" action="?/watch"><input type="hidden" name="id" value={item.id}/><button class="quiet">Watch</button></form>{/if}<details><summary>Feedback</summary><form method="POST" action="?/feedback"><input type="hidden" name="id" value={item.id}/><label class="sr-only" for={'feedback-'+item.id}>Feedback for {item.title}</label><select id={'feedback-'+item.id} name="kind"><option value="helpful">Helpful</option><option value="wrong-recommendation">Wrong recommendation</option><option value="wrong-data">Wrong data</option><option value="not-helpful">Not helpful</option><option value="should-not-run">Should not have run</option></select><button class="quiet">Send feedback</button></form></details></div></article>{:else}<p class="muted">No active priorities were found in the modules checked.</p>{/each}</section>
 <section><h2>Needs your decision</h2>{#each data.briefing.needsDecision as workflow}<article><h3>{workflow.goal}</h3>{#each workflow.steps as step}<p>{step.status.replaceAll('_',' ')} · {step.capabilityId} — {step.rationale}</p>{#if step.status==='waiting_approval' && step.input}<dl>{#each approvalFields.filter(k=>typeof step.input?.[k]==='string') as key}<dt class="muted">{key}</dt><dd>{String(step.input[key])}</dd>{/each}</dl>{/if}{/each}<form method="POST" action="?/workflow"><input type="hidden" name="id" value={workflow.id}/><input type="hidden" name="operation" value="approve"/><button>Approve next action</button></form><form method="POST" action="?/workflow"><input type="hidden" name="id" value={workflow.id}/><input type="hidden" name="operation" value="dismiss"/><button class="quiet">Don’t continue</button></form></article>{:else}<p class="muted">No workflow is waiting for your approval.</p>{/each}</section>
 <section><h2>At risk</h2>{#each data.briefing.atRisk as item}<article><h3>{item.title}</h3><p>{item.explanation}</p><a href={sourceHref(data.basePath,item.source)}>Review {item.source.module}</a></article>{:else}<p class="muted">No active risks in the current checks.</p>{/each}</section>
 <section><h2>Bob handled</h2>{#each data.briefing.handled as workflow}<article><h3>{workflow.goal}</h3><p>Completed · {date(workflow.updatedUtc)}</p></article>{:else}<p class="muted">No completed Bob workflows yet.</p>{/each}</section>
 <section><h2>Watching</h2>{#each data.briefing.watching as workflow}<article><h3>{workflow.goal}</h3><p>Waiting on a recorded source condition. Checked during briefing refresh.</p></article>{:else}<p class="muted">No active condition watches.</p>{/each}</section>
 {/if}
 {/if}
 {#if data.activity}<section><h2>Recent activity</h2><p class="muted">{data.activity.metrics.completed} completed · {data.activity.metrics.waitingApproval} awaiting approval · {data.activity.metrics.failed} need review</p>{#each data.activity.workflows as w}<article><h3>{w.goal}</h3><p>{w.status.replaceAll('_',' ')} · {date(w.updatedUtc)}</p>{#if w.failure}<p role="status">{w.failure}</p>{/if}{#each w.steps as s}<p>{s.capabilityId} · {s.status.replaceAll('_',' ')} · {s.rationale}</p>{/each}{#if w.status==='ready'}<form method="POST" action="?/workflow"><input type="hidden" name="id" value={w.id}/><input type="hidden" name="operation" value="advance"/><button>Continue</button></form>{/if}</article>{/each}{#each [...data.activity.events].reverse() as e}<article><p>{e.action.replaceAll('.',' ')} · {date(e.atUtc)}</p><p class="muted">{e.rationale}</p></article>{/each}</section>{/if}
 {#if data.automation}
 <form method="POST" action="?/policy&view=automation"><input type="hidden" name="version" value={data.automation.version}/><section><h2>Bob authority</h2><label class="toggle"><input type="checkbox" name="enabled" checked={data.automation.policy.enabled}/> Bob enabled</label><label class="toggle"><input type="checkbox" name="proactive" checked={data.automation.policy.proactiveEnabled}/> Proactive attention during source checks</label><label class="toggle"><input type="checkbox" name="external" checked={data.automation.policy.externalNotificationsEnabled}/>Allow approved external communication</label><fieldset><legend>Available modules</legend><div class="modules">{#each ['bob','leads','estimates','jobs','calendar','inventory','purchasing','finance','payroll'] as module}<label class="toggle"><input type="checkbox" name="module" value={module} checked={data.automation.policy.enabledModules.includes(module)}/>{module}</label>{/each}</div></fieldset></section>
 <section><h2>Approval policies</h2><p class="muted">External and high-risk actions retain human approval. Module permissions and validation always apply.</p>{#each data.automation.capabilities as c}<div class="policy-row"><label for={'policy-'+c.id}>{c.id}<span class="muted">{riskLabels[c.risk]} risk</span></label><select id={'policy-'+c.id} name={'policy:'+c.id}>{#each autonomyLabels as label,i}<option value={i} selected={(data.automation.policy.actions[c.id]??(c.writePermissions.length?3:4))===i}>{label}</option>{/each}</select></div>{/each}<button>Save authority</button></section></form>
 <section><h2>Active automations</h2>{#each data.automation.rules as r}<article><h3>{r.name}</h3><p>{r.enabled?'Enabled':'Disabled'} · {r.module} · {r.condition}</p></article>{:else}<p class="muted">No configured rules.</p>{/each}
 <form method="POST" action="?/rule&view=automation" class="stack"><input type="hidden" name="version" value={data.automation.version}/><label>Rule name<input name="name" required maxlength="120"/></label><label>Module<select name="module">{#each data.automation.policy.enabledModules.filter(m=>m!=='bob') as m}<option>{m}</option>{/each}</select></label><label>Source condition<select name="condition">{#each conditions as c}<option>{c}</option>{/each}</select></label><label class="toggle"><input type="checkbox" name="enabled"/>Enable this attention rule</label><button>Add attention rule</button></form></section>
 <section><h2>Escalations</h2>{#each data.automation.policy.escalations as e}<p>{e.module} · {e.condition} · {e.afterHours} hours → {e.team}</p>{/each}<form method="POST" action="?/escalation&view=automation" class="stack"><input type="hidden" name="version" value={data.automation.version}/><label>Module<select name="module">{#each data.automation.policy.enabledModules.filter(m=>m!=='bob') as m}<option>{m}</option>{/each}</select></label><label>Source condition<select name="condition">{#each conditions as c}<option>{c}</option>{/each}</select></label><label>Hours after deadline<input name="hours" type="number" min="0" max="8760" required/></label><label>Notify team in briefing<input name="team" maxlength="100" required/></label><button>Add escalation</button></form></section>
 <section><h2>Suggested automations</h2>{#each data.automation.suggestions as suggestion}<article><h3>{suggestion.title}</h3><p>{suggestion.description}</p></article>{/each}</section>
 {/if}
</div>
<style>
 .intelligence{max-width:960px;margin:auto;color:var(--text-strong);padding:8px 0 40px}header,.row,.actions{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}h1{font-size:1.7rem;font-weight:650;margin:4px 0}h2{font-size:1.1rem;font-weight:650;margin-bottom:16px}h3{font-weight:600;margin:8px 0}p{margin:6px 0;line-height:1.55}.eyebrow,.severity{font-size:.75rem;font-weight:650;text-transform:uppercase;letter-spacing:.07em}.muted{color:var(--text-muted);font-size:.875rem}nav{display:flex;gap:6px}a,button{min-height:44px;display:inline-flex;align-items:center;padding:8px 12px;border-radius:5px;font-size:.875rem;font-weight:600}a{text-decoration:underline;text-underline-offset:4px}nav a{text-decoration:none}nav a[aria-current]{background:var(--surface);box-shadow:inset 0 -2px var(--accent-text)}button{background:var(--cta);color:white;border:0;cursor:pointer}.quiet{background:transparent;color:var(--text-strong)}section{margin-top:32px}article{padding:16px 0;border-bottom:1px solid var(--border)}.actions{justify-content:flex-start;margin-top:10px}.actions form{display:flex;gap:8px;flex-wrap:wrap}summary{cursor:pointer;min-height:44px;padding:10px 12px;font-size:.875rem}details[open]{flex-basis:100%}input:not([type=checkbox]),select{min-height:44px;border:1px solid var(--border);border-radius:5px;background:var(--surface);color:var(--text-strong);padding:8px 10px;max-width:100%}.command{margin:28px 0 18px}.command label{display:flex;justify-content:space-between;font-size:.875rem;margin-bottom:8px}.command>div{display:flex;gap:8px}.command input{flex:1;min-width:0}.notice{padding:14px;background:var(--surface);border-left:3px solid var(--accent-text);margin:16px 0}.toggle{display:flex;align-items:center;gap:10px;min-height:44px}.modules{display:flex;flex-wrap:wrap;gap:4px 20px}fieldset{margin-top:16px}.policy-row{display:grid;grid-template-columns:1fr minmax(180px,240px);gap:16px;padding:12px 0;border-bottom:1px solid var(--border)}.policy-row label span{display:block}.policy-row:last-of-type{margin-bottom:16px}.stack{display:grid;gap:12px;max-width:500px;margin-top:20px}.stack>label:not(.toggle){display:grid;gap:6px;font-size:.875rem}.stack button{justify-self:start}:is(a,button,input,select):focus-visible{outline:3px solid var(--accent-text);outline-offset:3px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:600px){.policy-row{grid-template-columns:1fr;gap:6px}header{align-items:flex-start;flex-direction:column}.actions{align-items:center;gap:8px}}
</style>
